var t=`0635-roz-meammar`;var n=`world-0635`;var a=`EG`;var r=`northern-africa`;var s=4;var o=65;var m={en:`Roz Meammar`,ua:`Роз муаммар`};var l={en:`Roz Meammar is a Egypt classic prepared with white rice, whole cow milk, heavy cream. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Роз муаммар, страва кухні країни Єгипет зі складниками: білий рис, цільне коров'яче молоко, вершки високої жирності. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`white-rice`,310,`g`],[`whole-cow-milk`,750,`ml`],[`heavy-cream`,180,`ml`],[`unsalted-butter`,55,`g`],[`table-salt`,5,`g`]]},{en:`Bake rice with milk and cream in a covered earthenware or ovenproof dish at moderate heat until softly set and golden on top.`,ua:`Запікайте рис із молоком і вершками в закритій жаростійкій формі на помірному жарі до ніжної консистенції та золотистої поверхні.`,t:[`roasting`],m:55,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,15,`g`]]}];var h={slug:t,id:n,country:`EG`,region:r,servings:4,minutes:65,title:m,text:l,steps:d};export{a as country,h as default,n as id,o as minutes,r as region,s as servings,t as slug,d as steps,l as text,m as title};